  'Message could not be saved.' => 'Mesaj kaydedilemedi.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API (version %s) could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API (sürüm %s) bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.',
  'No WhatsApp connection.' => 'WhatsApp bağlantısı yok.',
  'Connected ✓' => 'Bağlı ✓',
  'Not connected (state: %s). Connect with QR.' => 'Bağlı değil (durum: %s). QR ile bağlayın.',
  'Webhook points to this site ✓' => 'Webhook bu siteye ayarlı ✓',
  'Evolution API version: %s' => 'Evolution API sürümü: %s',
  '(old: replies to hidden-number (@lid) contacts may fail, update to 2.3 or later)' => '(eski: gizli numaralı (@lid) kişilere cevap gidemeyebilir, 2.3 veya üstüne güncelleyin)',
  'The webhook is not pointed at this site. Press "Set up webhook".' => 'Webhook bu siteye ayarlı değil. "Webhook\'u kur" düğmesine basın.',
  'Webhook set up ✓ Incoming messages will now arrive here.' => 'Webhook kuruldu ✓ Artık gelen mesajlar buraya düşer.',
  'Importing recent chats, this may take a while…' => 'Son sohbetler içe aktarılıyor, bu biraz sürebilir…',
  'Messages stored in Evolution: %s' => 'Evolution\'da kayıtlı mesaj: %s',
  'Evolution does not store messages, so older messages cannot be loaded. On the Evolution server set DATABASE_SAVE_DATA_NEW_MESSAGE and DATABASE_SAVE_DATA_HISTORIC to true; for older conversations, keep "Sync full history" on in the instance settings when you reconnect the line with QR.' => 'Evolution mesajları kaydetmiyor, bu yüzden eski mesajlar gelemez. Evolution sunucusunda DATABASE_SAVE_DATA_NEW_MESSAGE ve DATABASE_SAVE_DATA_HISTORIC değerlerini true yapın; eski konuşmalar için hattı QR ile yeniden bağlarken instance ayarında "Sync full history" açık olsun.',
  '%1$s chats, %2$s messages imported ✓' => '%1$s sohbet, %2$s mesaj içe aktarıldı ✓',
  'Scan this code via WhatsApp › Linked devices › Link a device.' => 'WhatsApp › Bağlı cihazlar › Cihaz bağla ile bu kodu okutun.',
  'Pairing code:' => 'Eşleştirme kodu:',
  'This line is already connected ✓' => 'Bu hat zaten bağlı ✓',
  'Save the settings first.' => 'Önce ayarları kaydedin.',
  'Error:' => 'Hata:',
  'Delete this connection? Chat history is kept.' => 'Bu bağlantı silinsin mi? Sohbet geçmişi silinmez.',
  'Asking the AI…' => 'Yapay zekâya soruluyor…',
  'Working ✓ (%2$s ms): %1$s' => 'Çalışıyor ✓ (%2$s ms): %1$s',
  'Save the key and model first.' => 'Önce anahtarı ve modeli kaydedin.',
  'Connections' => 'Bağlantılar',
  'Auto replies' => 'Otomatik yanıtlar',
  'AI and assistant' => 'Yapay zekâ ve asistan',
  'System check' => 'Sistem kontrolü',
  'Connect your WhatsApp line, manage auto replies and labels.' => 'WhatsApp hattınızı bağlayın, otomatik yanıtları ve etiketleri yönetin.',
  'Open chats' => 'Sohbetleri aç',
  'Settings saved.' => 'Ayarlar kaydedildi.',
  'Connections and settings the call center needs. Saved status is shown; use the "test" buttons on each tab for a live check. The same checks also appear with the other plugins on the theme\'s system-check screen.' => 'Çağrı Merkezi\'nin çalışması için gereken bağlantılar ve ayarlar. Kayıtlı durumlar gösterilir; canlı deneme için ilgili sekmedeki "test et" düğmelerini kullanın. Aynı kontroller temanın sistem kontrolü ekranında diğer eklentilerle birlikte de görünür.',
  'WhatsApp lines' => 'WhatsApp hatları',
  'Messages are sent and received through Evolution API. WhatsApp connections are managed in Flux Mail; choose which one to use here. The URL and API key stay there, so you do not need to update them here when they change.' => 'Mesajlar Evolution API üzerinden gönderilir ve alınır. WhatsApp bağlantıları Flux Mail\'de yönetilir; burada hangisinin kullanılacağını seçin. Adres ve API key orada kalır, değişince burada ayrıca güncellemek gerekmez.',
  'Communication › Connections' => 'İletişim › Bağlantılar',
  'Messages are sent and received via Evolution API. If an Evolution provider is set up in Flux Certificates, you can pick the same connection; the URL and API key stay there.' => 'Mesajlar Evolution API üzerinden gönderilir ve alınır. Flux Certificates eklentisinde Evolution sağlayıcısı tanımlıysa aynı bağlantıyı seçebilirsiniz; adres ve API key orada kalır.',
  'Add line' => 'Hat ekle',
  'Setup steps' => 'Kurulum adımları',
  'Add the line and save.' => 'Hattı ekleyip kaydedin.',
  'Use "Test connection" to see that Evolution is reachable. If the line is not linked, choose "Connect with QR" and scan it from the phone.' => '"Bağlantıyı test et" ile Evolution\'a ulaşıldığını görün. Hat bağlı değilse "QR ile bağla" deyip telefondan okutun.',
  'Press "Set up webhook". Incoming messages, and messages sent from the phone and from Flux Certificates, then appear here live.' => '"Webhook\'u kur" düğmesine basın. Gelen mesajlar, telefondan ve Flux Certificates\'dan gönderilenler canlı olarak buraya düşer.',
  'Optionally bring in past messages with "Import recent chats".' => 'İsterseniz "Son sohbetleri içe aktar" ile geçmiş mesajları getirin.',
  'connected' => 'bağlı',
  'connecting' => 'bağlanıyor',
  'not connected' => 'bağlı değil',
  'not on server' => 'sunucuda yok',
  'unreachable' => 'ulaşılamıyor',
  'Flux Mail connection: %s' => 'Flux Mail bağlantısı: %s',
  'Flux Mail connection #%d (not found or disabled)' => 'Flux Mail bağlantısı #%d (bulunamadı ya da kapalı)',
  'Use Flux Certificates provider: %s' => 'Flux Certificates sağlayıcısını kullan: %s',
  'Enter separate Evolution API details' => 'Ayrı Evolution API bilgisi gir',
  'Line name (e.g. Main line)' => 'Hat adı (ör. Ana hat)',
  'Connection details' => 'Bağlantı bilgisi',
  'API URL' => 'API adresi',
  'Instance name' => 'Instance adı',
  'API key (apikey)' => 'API key (apikey)',
  '•••••••• (saved; type to change)' => '•••••••• (kayıtlı; değiştirmek için yazın)',
  'Webhook URL' => 'Webhook adresi',
  'Regenerate secret key' => 'Gizli anahtarı yenile',
  'Last webhook: %s' => 'Son webhook: %s',
  'No webhook received yet.' => 'Henüz webhook gelmedi.',
  'Test connection' => 'Bağlantıyı test et',
  'Connect with QR' => 'QR ile bağla',
  'QR, status and accounts: Communication › Connections' => 'QR, durum ve hesaplar: İletişim › Bağlantılar',
  'Set up webhook' => 'Webhook\'u kur',
  'Import recent chats' => 'Son sohbetleri içe aktar',
  'The webhook URL and test buttons appear after saving.' => 'Kaydettikten sonra webhook adresi ve test düğmeleri görünür.',
  'Appearance' => 'Görünüm',
  'Panel title' => 'Panel başlığı',
  'Site name if empty. The {brand} variable uses this too.' => 'Boş bırakılırsa site adı. {brand} değişkeni de bunu kullanır.',
  'Accent color' => 'Vurgu rengi',
  'Behavior' => 'Çalışma şekli',
  'Send read receipts (blue ticks) when a chat is opened' => 'Sohbet açılınca karşı tarafa okundu bilgisi (mavi tik) gönder',
  'Prefix messages with the agent\'s name (*Name:*)' => 'Mesajın başına temsilci adını ekle (*Ad:*)',
  'Agents see only chats assigned to them and unassigned chats (admins see all)' => 'Temsilciler yalnız kendine atanan ve atanmamış sohbetleri görsün (yöneticiler hepsini görür)',
  'Also show WhatsApp group messages' => 'WhatsApp grup mesajlarını da göster',
  'New interface (experimental): the Chats page opens with the same screen as the desktop and mobile app' => 'Yeni arayüz (deneysel): Sohbetler sayfası masaüstü ve mobil uygulamayla aynı ekranla açılır',
  'Live update interval (sec)' => 'Canlı güncelleme sıklığı (sn)',
  'Agents' => 'Temsilciler',
  'Give a user the %s role; they see only the chat screen and cannot open settings. Administrators always have access.' => 'Bir kullanıcıya %s rolü verin; yalnız sohbet ekranını görür, ayarlara giremez. Yöneticiler her zaman erişir.',
  'Add new user' => 'Yeni kullanıcı ekle',
  'Data' => 'Veri',
  'Also delete all chats, messages and media files when the plugin is deleted' => 'Eklenti silinirken tüm sohbetleri, mesajları ve medya dosyalarını da sil',
  'Media files are kept in wp-content/uploads/flx-chat, closed to outside access. They move with uploads when the site is migrated.' => 'Medya dosyaları wp-content/uploads/flx-chat klasöründe, dışarıdan erişime kapalı tutulur. Site taşınırken uploads ile birlikte gider.',
  'Mon' => 'Pzt',
  'Tue' => 'Sal',
  'Wed' => 'Çar',
  'Thu' => 'Per',
  'Fri' => 'Cum',
  'Sat' => 'Cmt',
  'Sun' => 'Paz',
  'Welcome message' => 'Karşılama mesajı',
  'Send automatically to people who write to us for the first time' => 'Bize ilk kez yazan kişiye otomatik gönder',
  'Away message' => 'Mesai dışı yanıtı',
  'Auto reply to messages received outside business hours' => 'Mesai saatleri dışında gelen mesajlara otomatik yanıt ver',
  'Business days' => 'Mesai günleri',
  'Start' => 'Başlangıç',
  'End' => 'Bitiş',
  'At most once per contact every (hours)' => 'Aynı kişiye en fazla (saatte bir)',
  'Timezone: %1$s. Now: %2$s.' => 'Saat dilimi: %1$s. Şu an: %2$s.',
  'within business hours' => 'mesai içi',
  'outside business hours' => 'mesai dışı',
  'The {first_name}, {name}, {brand}, {site}, {date} variables can be used in the texts.' => 'Metinlerde {first_name}, {name}, {brand}, {site}, {date} değişkenleri kullanılabilir.',
  'Chat labels' => 'Sohbet etiketleri',
  'Label chats and filter the list (e.g. Donation, Complaint, Follow-up).' => 'Sohbetleri etiketleyip listede filtreleyin (ör. Bağış, Şikâyet, Takip).',
  'Add label' => 'Etiket ekle',
  'Label name' => 'Etiket adı',
  'Creating records from chats' => 'Sohbetten kayıt oluşturma',
  'Buttons in the chat header create a donation record (Flux Donate) and a certificate (Flux Certificates), and an incoming receipt is matched with a record. If a plugin is not installed, its button is hidden.' => 'Sohbet başlığındaki düğmelerle bağış kaydı (Flux Donate) ve sertifika (Flux Certificates) oluşturulur, gelen dekont kayıtla eşleştirilir. Eklenti kurulu değilse ilgili düğme görünmez.',
  'Agents can create donation records and match receipts' => 'Temsilciler bağış kaydı oluşturabilsin ve dekont eşleştirebilsin',
  'Agents can create and send certificates' => 'Temsilciler sertifika oluşturup gönderebilsin',
  'Show quick reply bubbles above the message box' => 'Mesaj kutusunun üstünde hazır cevap baloncuklarını göster',
  'Donation messages' => 'Bağış mesajları',
  'Ready texts sent to the person when a record is created (editable before sending). If left empty, the default text is used.' => 'Kayıt oluşturulunca kişiye gönderilecek hazır metinler (gönderimden önce düzenlenebilir). Boş bırakılırsa varsayılan metin kullanılır.',
  'Awaiting payment (promised transfer)' => 'Ödeme bekleniyor (havale sözü)',
  'Donation received' => 'Bağış alındı',
  'Receipt confirmed' => 'Dekont onaylandı',
  'Bank details ({bank})' => 'Banka bilgisi ({bank})',
  'Recipient name, bank, IBAN' => 'Alıcı adı, banka, IBAN',
  'If empty, the account in WooCommerce › Payments › Bank transfer is used.' => 'Boşsa WooCommerce › Ödemeler › Havale / EFT ayarındaki hesap kullanılır.',
  'Variables: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Değişkenler: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.',
  'AI connection' => 'Yapay zekâ bağlantısı',
  'Keys, prompt caching, spending limits and usage logs come from the Flux AI & MCP plugin; all of the Call Center\'s AI requests go through it. Model choices stay here; if a field is empty, the model chosen for this plugin in Flux AI (or the default) is used.' => 'Anahtarlar, prompt önbelleği, harcama sınırı ve kullanım kayıtları Flux AI & MCP eklentisinden gelir; Çağrı Merkezi\'nin tüm yapay zekâ istekleri oradan geçer. Model seçimleri burada kalır; alanlar boşsa Flux AI\'de bu eklentiye seçilen model (ya da varsayılan) kullanılır.',
  'Open Flux AI settings' => 'Flux AI ayarlarını aç',
  'AI needs the Flux AI & MCP plugin. Install and activate it, then enter the OpenRouter and/or Anthropic key in Flux AI & MCP › Settings. Until then suggestions, the assistant, receipt reading, voice messages and summaries are off.' => 'Yapay zekâ için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a OpenRouter ve/veya Anthropic anahtarını girin. O zamana kadar öneri, asistan, dekont okuma, sesli mesaj ve özet kapalıdır.',
  'Creativity (0–1)' => 'Yaratıcılık (0–1)',
  'Lower values give more consistent replies, higher values freer ones. 0.4 recommended.' => 'Düşük değer daha tutarlı, yüksek değer daha serbest cevap verir. Önerilen 0,4.',
  'Model (for suggestions)' => 'Model (öneriler için)',
  'Assistant model (optional)' => 'Asistan modeli (isteğe bağlı)',
  'Model above' => 'Yukarıdaki model',
  'Only models that support tools are listed.' => 'Yalnız araç (tools) destekleyen modeller listelenir.',
  'Receipt reading model (optional)' => 'Dekont okuma modeli (isteğe bağlı)',
  'If the selected model cannot read images, a cheap vision model is used automatically.' => 'Seçilen model görsel okuyamıyorsa görsel okuyan ucuz bir modele kendiliğinden geçilir.',
  'This month (%1$s): %2$s requests, %3$s tokens, about $%4$s.' => 'Bu ay (%1$s): %2$s istek, %3$s token, yaklaşık $%4$s.',
  'Reply suggestions' => 'Cevap önerisi',
  'Above the message box, the next message is suggested from the conversation. The agent clicks "Send" or takes it into the box with "Edit". A suggestion is never sent on its own.' => 'Mesaj kutusunun üstünde, konuşmaya göre sıradaki mesaj önerilir. Temsilci "Gönder" der ya da "Düzenle" ile kutuya alıp değiştirir. Öneri asla kendiliğinden gönderilmez.',
  'Prepare a suggestion automatically when the last message came from the person (if off, ask with the ✨ button)' => 'Son mesaj kişiden geldiyse öneri kendiliğinden hazırlansın (kapalıysa ✨ düğmesiyle istenir)',
  'Organization info and tone' => 'Kurum bilgisi ve üslup',
  'E.g. Our association plants saplings in Istanbul. Planting is done every year between November and March. The certificate is sent on WhatsApp after the donation. Use a warm but formal tone.' => 'Ör. Derneğimiz İstanbul\'da fidan dikimi yapar. Dikimler her yıl Kasım–Mart arasında yapılır. Sertifika bağıştan sonra WhatsApp\'tan gönderilir. Samimi ama resmi bir dil kullan.',
  'Suggestions and the assistant use this. Donation types, prices, bank details and quick replies are added automatically.' => 'Öneri ve asistan bu bilgileri kullanır. Bağış türleri, fiyatlar, banka bilgisi ve hazır cevaplar ayrıca otomatik eklenir.',
  'Suggestion provider' => 'Öneri sağlayıcısı',
  'Donation assistant (automatic replies)' => 'Bağış asistanı (otomatik cevap)',
  'When on, the assistant replies itself: it greets, asks the name to address them, sends donation options and prices, optionally collects email and "in whose name", and asks for confirmation after each change. After confirmation it opens an "awaiting payment" record in Flux Donate and sends the donation link, recipient, IBAN and reference as separate messages. If the topic leaves donations, it hands the chat to the team.' => 'Açıkken asistan gelen mesajlara kendisi cevap verir: karşılar, hitap için adını sorar, bağış seçeneklerini ve fiyatları gönderir, isteğe bağlı e-posta ve "kimin adına" bilgilerini alır, her değişiklikte özet gösterip onay ister. Onaydan sonra Flux Donate\'ta "ödeme bekleniyor" kaydı açar ve bağış linki ile alıcı adı, IBAN, açıklamayı ayrı mesajlar hâlinde gönderir. Konu bağış dışına çıkarsa sohbeti ekibe devreder.',
  'The Flux Donate plugin is not active; the assistant cannot create donation records.' => 'Flux Donate eklentisi etkin değil; asistan bağış kaydı açamaz.',
  'Instructions, documents, AI chats and test chat' => 'Talimat, belgeler, AI sohbetleri ve test sohbeti',
  'Turn on the donation assistant (untick to turn it off everywhere)' => 'Bağış asistanını aç (tümünü kapatmak için işareti kaldırın)',
  'Which chats should it reply to' => 'Hangi sohbetlerde cevap versin',
  'In all chats (recommended)' => 'Tüm sohbetlerde (önerilen)',
  'In chats not assigned to an agent' => 'Temsilciye atanmamış sohbetlerde',
  'Only outside working hours' => 'Yalnız mesai saatleri dışında',
  'When an agent writes in a chat (from the panel or the phone), the assistant stays quiet there for the time below. Use the assistant button in the chat header to turn it on or off per chat.' => 'Bir temsilci sohbete yazdığında (panelden ya da telefondan) asistan o sohbette aşağıdaki süre kadar susar. Sohbet başlığındaki asistan düğmesiyle sohbet bazında açılıp kapatılır.',
  'Test mode: reply only to the numbers below' => 'Test modu: yalnız aşağıdaki numaralarda cevap ver',
  'Test numbers' => 'Test numaraları',
  'Separate with commas or new lines. Not used when test mode is off.' => 'Virgül ya da satır ile ayırın. Test modu kapalıyken kullanılmaz.',
  'Quiet after an agent writes (hours)' => 'Temsilci yazınca susma (saat)',
  'Quantities in the price list' => 'Fiyat listesindeki adetler',
  'Conversation history (hours)' => 'Konuşma geçmişi (saat)',
  'Before replying, the assistant reads all messages from this period.' => 'Asistan cevaptan önce bu süredeki tüm mesajları okur.',
  'Donation types the assistant offers' => 'Asistanın sunduğu bağış türleri',
  'If none is selected, all open types are offered. When a new type is opened in Flux Donate, the assistant knows it too.' => 'Hiçbiri seçilmezse açık olan tüm türler sunulur. Yeni tür Flux Donate\'ta açıldığında asistan onu da bilir.',
  'Receipt pre-check: when the contact sends a receipt, AI compares the amount, recipient and IBAN with the donation, tells the contact the result, attaches the file to the donation record and hands the chat to the team for final approval (does not mark it paid)' => 'Dekont ön kontrolü: kişi dekont gönderince yapay zekâ tutarı, alıcıyı ve IBAN\'ı bağışla karşılaştırır, sonucu kişiye söyler, dosyayı bağış kaydına ekler ve son onay için sohbeti ekibe devreder (ödendi işaretlemez)',
  'Last line of the price list' => 'Fiyat listesinin son satırı',
  'Payment details' => 'Ödeme bilgileri',
  'If the recipient and IBAN are empty, those in WooCommerce › Payments › Bank transfer are used (the account shown on orders). Fill them in only if the assistant should use a different account.' => 'Alıcı adı ve IBAN boşsa WooCommerce › Ödemeler › Havale / EFT ayarındakiler kullanılır (siparişlerde görünen hesap). Yalnız asistan için farklı hesap istiyorsanız doldurun.',
  'Recipient name' => 'Alıcı adı',
  'Transfer description' => 'Havale açıklaması',
  'Variables: {type}, {name}, {amount}, {quantity}' => 'Değişkenler: {type}, {name}, {amount}, {quantity}',
  'Donation page URL' => 'Bağış sayfası adresi',
  'The selected type and quantity are added to the link (?flxb_opt=…&flxb_qty=…).' => 'Linke seçilen tür ve adet eklenir (?flxb_opt=…&flxb_qty=…).',
  'Message after the payment details' => 'Ödeme bilgilerinden sonraki mesaj',
  'Donation cancellation question' => 'Bağış iptali onay sorusu',
  'The assistant cancels only unpaid donations, with the person\'s confirmation. Empty = default text. Variables: {bagis}, {tutar}.' => 'Asistan yalnız ödenmemiş bağışları, kişinin onayıyla iptal eder. Boşsa varsayılan metin. Değişkenler: {bagis}, {tutar}.',
  'Message sent when the daily limit is reached' => 'Günlük sınır dolunca gönderilen mesaj',
  'Sent once when a chat reaches the day\'s reply limit; the chat is handed to the team. Reset it from the chat\'s ⋮ menu › Assistant usage.' => 'Sohbet o günkü cevap sınırına ulaşınca bir kez gider, sohbet ekibe devredilir. Sınır sohbetin ⋮ menüsü › Asistan kullanımı ekranından sıfırlanır.',
  'Message sent when handing over to the team' => 'Ekibe devrederken gönderilen mesaj',
  'Message sent when the assistant cannot answer' => 'Asistan cevap veremezse giden mesaj',
  'If the AI fails, the time limit is hit or the queue gets too long, this message is sent and the chat is handed to the team; the person is never left without an answer.' => 'Yapay zekâ hata verir, süre aşılır ya da yoğunlukta sıra çok uzarsa kişiye bu mesaj gider ve sohbet ekibe devredilir; kişi hiçbir durumda cevapsız kalmaz.',
  'Minimum wait before the holding message (s)' => 'Bekleme mesajından önce en az (sn)',
  'The holding message is not sent until this many seconds after the person\'s message; meanwhile the assistant retries.' => 'Kişinin mesajından bu kadar saniye geçmeden bekleme mesajı gitmez; bu arada asistan yeniden dener.',
  'Longest time for one answer (s)' => 'Bir cevabın en uzun süresi (sn)',
  'Hostinger can cut requests at ~60 s; 50 is recommended.' => 'Hostinger istekleri ~60 sn\'de kesebilir; 50 önerilir.',
  'Numbers notified on handoff' => 'Devirde bildirim gidecek numaralar',
  'When the assistant hands a chat over to the team, a WhatsApp message is sent to these numbers from the same line: the contact\'s name, phone, reason, last messages and panel link. Separate with commas or new lines. The assistant does not talk to these numbers.' => 'Asistan bir sohbeti ekibe devredince bu numaralara aynı hattan WhatsApp mesajı gider: kişinin adı, telefonu, nedeni, son mesajları ve panel linki. Virgül ya da satır ile ayırın. Bu numaralarla asistan konuşmaz.',
  'When the contact writes one of these, the assistant immediately sends the hand-off message above and turns off in that chat. If left empty, the example list is used.' => 'Kişi bunlardan birini yazınca asistan beklemeden yukarıdaki devir mesajını gönderir ve o sohbette kapanır. Boş bırakılırsa örnekteki liste kullanılır.',
  'Extra instructions for the assistant' => 'Asistana ek talimatlar',
  'E.g. Saplings are planted in Kocaeli. Certificates are sent once the donation is confirmed.' => 'Ör. Fidanların dikileceği yer: Kocaeli. Sertifikalar bağış onaylanınca gönderilir.',
  'Last message when a contact opts out' => 'Kişi mesaj istemeyince gönderilen son mesaj',
  'If someone writes something like "don\'t message me", the assistant sends this message and blocklists them. A blocklisted person gets no WhatsApp, email or SMS; manage the list under Chats › ☰ › Blocklist.' => 'Kişi "bana mesaj atmayın" gibi bir şey yazınca asistan bu mesajı gönderir ve kişiyi kara listeye alır. Kara listedeki kişiye WhatsApp, e-posta ve SMS gitmez; listeyi Sohbetler › ☰ › Kara liste\'den yönetirsiniz.',
  'Contact memory and background jobs' => 'Kişi hafızası ve arka plan işleri',
  'Contact memory: the assistant remembers lasting details (form of address, relatives\' names, numbers, preferences); expired chats are summarized' => 'Kişi hafızası: asistan kişinin kalıcı bilgilerini (hitap, yakınlarının adı, numaralar, tercihler) hatırlar; süresi dolan sohbetler özetlenir',
  'Summarize a chat after it has been quiet for (hours)' => 'Sohbet kaç saat sessiz kalınca özetlensin',
  'Maximum jobs at the same time' => 'Aynı anda en fazla iş',
  'How many people can be answered at the same time. Assistant replies always come first; summaries do not start while someone is being answered or waiting. Each job uses one PHP worker: on shared hosting, stay under half of the total worker limit of your sites (e.g. 20-30 of 60 workers).' => 'Aynı anda cevap yazılabilecek kişi sayısı. Asistan cevapları her zaman önce gelir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. Her iş bir PHP işçisi kullanır: paylaşımlı hostingde sitelerin toplam işçi sınırının yarısını geçmeyin (ör. 60 işçide 20-30).',
  'Workers reserved for replies' => 'Yalnız cevaplara ayrılan işçi',
  'This many workers never take summaries or reminders.' => 'Bu kadar işçi hiçbir zaman özet ya da hatırlatıcı almaz.',
  'Summary hours' => 'Özet saatleri',
  'Summaries run only between these hours (except a manual "Summarize now"). If both are the same, any time.' => 'Özetler yalnız bu saatler arasında yapılır (elle "Şimdi özetle" hariç). İkisi aynıysa her saat.',
  'When someone sends a voice message, the assistant turns it into text and replies (the text also appears in the panel as a system line)' => 'Kişi sesli mesaj gönderirse asistan sesi metne çevirip cevap versin (metin panelde sistem satırı olarak da görünür)',
  'Longest voice message (sec)' => 'En uzun ses (sn)',
  'For longer messages the assistant says "the voice message was too long for us to listen to".' => 'Daha uzun seslerde asistan "ses çok uzun olduğu için dinleyemedik" der.',
  'Voice message model (optional)' => 'Sesli mesaj modeli (isteğe bağlı)',
  'Cheap audio model (Gemini Flash Lite)' => 'Ses okuyan ucuz model (Gemini Flash Lite)',
  'Must be an OpenRouter model that accepts audio (Claude does not). An OpenRouter key is required.' => 'Ses okuyan bir OpenRouter modeli olmalı (Claude ses okumaz). OpenRouter anahtarı gerekir.',
  'Images' => 'Görseller',
  'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately' => 'Gerekince asistan görsel (tablo, rapor, şema) çizsin; WhatsApp\'a resim olarak gider, metin ayrıca gider',
  'The Flux AI image renderer is used (Flux AI & MCP › Settings › Images).' => 'Flux AI görsel çeviricisi kullanılır (Flux AI & MCP › Ayarlar › Görseller).',
  'No image renderer on the server: enter a Gotenberg address in Flux AI & MCP › Settings › Images or install Imagick (SVG). Until then the assistant does not draw images.' => 'Sunucuda görsel çevirici yok: Flux AI & MCP › Ayarlar › Görseller\'e Gotenberg adresi girin ya da Imagick (SVG) kurulsun. O zamana kadar asistan görsel çizmez.',
  'Works once Flux AI 0.2.0 or later is installed.' => 'Flux AI 0.2.0 ya da sonrası kurulunca çalışır.',
  'Donation on behalf of someone' => 'Başkası adına bağış',
  'If the donation is in someone else\'s name and their number was given (contact card or typed number), also send the certificate to that number on WhatsApp once the payment is approved' => 'Bağış başkası adınaysa ve o kişinin numarası verildiyse (kişi kartı ya da yazılı numara), ödeme onaylanınca sertifika o numaraya da WhatsApp\'tan gitsin',
  'Message sent before the certificate' => 'Sertifikadan önce giden mesaj',
  'Then the WhatsApp certificate message from Flux Certificates is sent. Variables: {ad}, {bagisci}, {bagis}, {brand}.' => 'Ardından Flux Certificates\'daki WhatsApp sertifika mesajı gider. Değişkenler: {ad}, {bagisci}, {bagis}, {brand}.',
  'If a person asks, the assistant sets up a reminder (e.g. "remind me of sapling planting every month", "send me your latest projects every month", "ask me for a sapling every month"); when it is due, the assistant writes and sends the message' => 'Kişi isterse asistan hatırlatıcı kurar (ör. "her ay fidan dikimini hatırlat", "her ay son projelerinizi gönderin", "her ay benden bir fidan iste"); zamanı gelince asistan mesajı yazıp gönderir',
  'When no time is given' => 'Saat söylenmezse',
  'At most per person' => 'Kişi başına en fazla',
  'Staff (Flux Roles)' => 'Personel (Flux Roles)',
  'Works once Flux Roles 1.1.0 is installed: users whose number is set in Profile › WhatsApp number get extra assistant tools based on their permissions.' => 'Flux Roles 1.1.0 kurulunca çalışır: numarası Profil › WhatsApp numarası alanına yazılmış kullanıcılar asistanda yetkilerine göre ek araçlar kullanır.',
  'Give staff numbers extra assistant tools by permission (donation on behalf of someone with payment link, my donors, general report)' => 'Personel numarasından yazana asistan yetkisine göre ek araçlar açsın (başkası adına bağış ve ödeme linki, bağışçılarım, genel rapor)',
  'Notify staff on WhatsApp when a donation they referred is paid or cancelled' => 'Referansı olduğu bağış ödenince ya da iptal olunca personele WhatsApp bildirimi gitsin',
  'First message to the donor for a donation opened by staff' => 'Personel adına açılan bağışta bağışçıya ilk mesaj',
  'Hello {ad} 🌱 Your {bagis} donation request via {personel} has been received. You can pay with the details below.' => 'Merhaba {ad} 🌱 {personel} aracılığıyla {bagis} bağış talebiniz alındı. Ödemeyi aşağıdaki bilgilerle yapabilirsiniz.',
  'The payment link and bank details follow. Variables: {ad}, {adsoyad}, {personel}, {bagis}.' => 'Ardından ödeme linki ve havale bilgileri gider. Değişkenler: {ad}, {adsoyad}, {personel}, {bagis}.',
  'When a donation referred by a staff member is paid and its certificates are made, send them to the staff member on WhatsApp too (just like the donor)' => 'Personelin referansı olduğu bağış ödenip sertifika oluşunca sertifika personele de WhatsApp\'tan gitsin (bağışçıya gittiği gibi)',
  'Message sent to the staff member before the certificate' => 'Personele sertifikadan önce giden mesaj',
  'Variables: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Değişkenler: {ad}, {bagisci}, {bagis}, {no}, {brand}.',
  'How many times staff can resend a donation\'s certificate' => 'Personel bir bağışın sertifikasını en fazla kaç kez yeniden gönderebilir',
  'The assistant lists the recipients and asks for confirmation before sending. 0: off.' => 'Asistan göndermeden önce kime gideceğini yazıp onay ister. 0: kapalı.',
  'Code verification for record lookups' => 'Kayıt sorgusunda kod doğrulama',
  'When a person asks for their records and their number is hidden (or they donated with another number/e-mail), send a code to the number or e-mail they give; once verified, its records are shown too' => 'Kişi kayıtlarını sorar ve numarası gizliyse (ya da başka numara/e-postayla bağış yaptıysa) verdiği numaraya ya da e-postaya kod gönder; kod doğrulanınca onun kayıtları da gösterilir',
  'Code validity (min)' => 'Kod geçerliliği (dk)',
  'Maximum failed attempts' => 'En fazla başarısız deneme',
  'Codes that could not be sent, wrong codes and expired codes count. At the limit the person gets the message below and the team is notified; the assistant keeps answering other questions but shares no record details for 24 hours.' => 'Gönderilemeyen, yanlış ya da süresi dolan kodlar sayılır. Sınırda kişiye aşağıdaki mesaj gider, ekibe haber verilir; asistan diğer sorulara cevap verir ama 24 saat kayıt bilgisi vermez.',
  'Code to phone' => 'Telefona kod',
  'WhatsApp, SMS if it fails' => 'WhatsApp, gitmezse SMS',
  'WhatsApp only' => 'Yalnız WhatsApp',
  'SMS only' => 'Yalnız SMS',
  'SMS is used if Flux Mail has an SMS connection (e.g. Netgsm).' => 'SMS, Flux Mail\'te SMS bağlantısı (ör. Netgsm) varsa kullanılır.',
  'Message when verification fails' => 'Doğrulama yapılamazsa giden mesaj',
  'WhatsApp/SMS code message' => 'WhatsApp/SMS kod mesajı',
  'Default text if empty. Variables: {kod}, {dk}, {marka}. The e-mail text is edited in Flux Mail › E-mail templates.' => 'Boşsa varsayılan metin. Değişkenler: {kod}, {dk}, {marka}. E-posta metni Flux Mail › E-posta şablonları\'ndan değişir.',
  'Site content' => 'Sitedeki içerikler',
  'Let the assistant search published site content (e.g. "do you have a post about tree planting")' => 'Asistan sitede yayında olan içeriklerde arama yapabilsin (ör. "fidan dikimi geçen bir gönderiniz var mı")',
  'Content types to search' => 'Aranacak içerik türleri',
  'Only published content without a password is returned. Drafts, private and password-protected content are never shown.' => 'Yalnız yayında ve şifresiz içerikler döner. Taslak, özel ve şifreli içerik hiçbir zaman gösterilmez.',
  'Categories and tags never to share' => 'Hiç paylaşılmayacak kategori ve etiketler',
  'e.g. corporate-offers, internal-notice' => 'ör. kurumsal-teklifler, ic-duyuru',
  'Name or slug, comma separated. To hide a single item, tick "Do not let the assistant share this content" on its edit screen.' => 'Ad ya da kısa ad, virgülle. Tek bir içeriği gizlemek için düzenleme ekranındaki "Asistan bu içeriği kişilerle paylaşmasın" kutusunu işaretleyin.',
  'Team group' => 'Ekip grubu',
  'WhatsApp group' => 'WhatsApp grubu',
  '— Not selected —' => '— Seçilmedi —',
  'Groups the line is a member of. If a group you just created is missing,' => 'Hattın üye olduğu gruplar. Yeni açtığınız grup görünmüyorsa',
  'refresh the list' => 'listeyi yenileyin',
  'Post incoming messages and replies (assistant, team, automatic) to this group' => 'Kişilerden gelen mesajları ve verilen cevapları (asistan, ekip, otomatik) bu gruba yaz',
  'Send handoff notifications to this group instead of each number; the numbers above are mentioned in the message' => 'Devir bildirimini numaralara ayrı ayrı değil bu gruba gönder; yukarıdaki numaralar mesajda etiketlenir',
  'Last post to the group failed: ' => 'Gruba son gönderim başarısız: ',
  'Price list preview' => 'Fiyat listesi önizlemesi',
  'Enter an AI key and model first so the assistant can work.' => 'Asistanın çalışması için önce yapay zekâ anahtarı ve model girin.',
  'The assistant will not reply right now: ' => 'Asistan şu an konuşmaz: ',
