  'Replies' => 'Cevap',
  'Handoff' => 'Devir',
  'Only real chats are counted; test chat and benchmark are excluded. "Confirmed" means donations created by the assistant and marked paid.' => 'Yalnız gerçek sohbetler sayılır; test sohbeti ve benchmark hariç. "Onaylanan" asistanın açtığı ve ödendi işaretlenen bağışlardır.',
  'With the team / paused' => 'Ekipte / beklemede',
  'Donation record created' => 'Bağış kaydı açılan',
  'The assistant has not replied to any chat yet.' => 'Asistan henüz bir sohbete cevap vermedi.',
