  'Version {id}' => 'Sürüm {id}',
  'Change note (e.g. Added sacrifice question)' => 'Değişiklik notu (ör. Kurban sorusu eklendi)',
  'Assistant instructions' => 'Asistan talimatı',
  'The main text describing how the assistant talks and the flow. Prices, donation types, bank details and what is known about the contact are added automatically on every reply. {brand} becomes the organisation name and {{belge:kisa-ad}} becomes that document\'s content.' => 'Asistanın nasıl konuşacağını ve akışı anlatan ana metin. Fiyatlar, bağış türleri, banka bilgisi ve kişinin bilinen bilgileri her cevapta otomatik eklenir. {brand} kurum adına, {{belge:kisa-ad}} o belgenin içeriğine dönüşür.',
  'Publish now' => 'Hemen yayına al',
