  'Show the full text sent to the model' => 'Modele giden tam metni gör',
  'Unsaved text' => 'Kaydedilmemiş metin',
  'Test with this text' => 'Bu metinle test et',
  'Versions' => 'Sürümler',
  'Live' => 'Yayında',
  'Text that ships with the plugin' => 'Eklentiyle gelen metin',
  'Diff: live → {v}' => 'Fark: yayındaki → {v}',
  'Show diff' => 'Farkı gör',
  'Published' => 'Yayına alındı',
  'Publish' => 'Yayına al',
  'Ready-made messages sent by the server' => 'Sunucunun gönderdiği hazır mesajlar',
  'The model does not write these; they are generated from your settings.' => 'Bu mesajları model yazmaz; ayarlardaki bilgilerden üretilir.',
  'Change in settings' => 'Ayarlarda değiştir',
  '(empty)' => '(boş)',
  'Full text sent to the model (sample chat)' => 'Modele giden tam metin (örnek sohbet)',
  'Extra documents' => 'Ek belgeler',
  'Add FAQs, campaigns, planting locations and similar information as separate documents. If you write {{belge:kisa-ad}} in the instructions, the document is placed there. A document set to "read when needed" is only read when the topic comes up, which costs less for long documents.' => 'Sık sorulan sorular, kampanya, dikim yerleri gibi bilgileri ayrı belgeler olarak ekleyin. Talimatta {{belge:kisa-ad}} yazarsanız belge oraya konur. "Gerektiğinde okur" seçilen belgeyi asistan yalnız konu açılınca okur; uzun belgeler için daha az maliyetlidir.',
  'New document' => 'Yeni belge',
  'No documents yet.' => 'Henüz belge yok.',
  'Copy to use in the instructions' => 'Talimatta kullanmak için kopyalayın',
  'Delete the document “{t}”?' => '“{t}” belgesi silinsin mi?',
  'automatic' => 'otomatik',
