  'E.g. Look at Ahmet\'s chat and make the price answer shorter. / Hand over to the team when asked about Qurban donations.' => 'Ör. Ahmet\'in sohbetine bak, fiyat sorusuna daha kısa cevap versin. / Kurban bağışı sorulursa ekibe devretsin.',
