  'The AI tries the draft here itself: it writes like a person and sees the assistant\'s answer. Nothing is sent to WhatsApp.' => 'Yapay zekâ taslağı burada kendisi dener: kişi gibi mesaj yazar, asistanın cevabını görür. WhatsApp\'a bir şey gitmez.',
