  'Your {marka} verification code: {kod}' => '{marka} doğrulama kodunuz: {kod}',
  'The code is valid for {dk} minutes. Type it in your WhatsApp chat with us. If you did not ask for it, ignore this message.' => 'Kod {dk} dakika geçerlidir. Bu kodu WhatsApp\'ta bizimle olan sohbete yazın. Bu isteği siz yapmadıysanız dikkate almayın.',
  'Something went wrong; our team will contact you as soon as possible 🌱 Meanwhile, feel free to ask anything else.' => 'Bir sıkıntı oldu, ekibimiz en kısa sürede sizinle iletişime geçecek 🌱 Bu arada başka bir sorunuz olursa yazabilirsiniz.',
  'Verification attempt failed (%1$d/%2$d): %3$s' => 'Doğrulama denemesi başarısız (%1$d/%2$d): %3$s',
  'The person wanted to see their records but could not be verified; someone from the team should get in touch' => 'Kişi kayıtlarını görmek istedi, doğrulama yapılamadı; ekipten biri iletişime geçmeli',
  'e-mail could not be sent (check Flux Mail › SMTP settings)' => 'e-posta gönderilemedi (Flux Mail › SMTP ayarlarını kontrol edin)',
  'The assistant sent a verification code for %1$s (%2$s).' => 'Asistan %1$s için doğrulama kodu gönderdi (%2$s).',
  'code expired' => 'kodun süresi doldu',
  'wrong code' => 'yanlış kod',
  'The person verified the code for %s; it is added to their record lookups.' => 'Kişi %s için kodu doğruladı; kayıt sorgusuna eklendi.',
  'Claude models cannot read audio; choose an audio-capable OpenRouter model in Settings › AI › Voice message model.' => 'Claude modelleri ses okuyamaz; Ayarlar › Yapay zekâ › Sesli mesaj modelinden ses okuyan bir OpenRouter modeli seçin.',
  'The audio could not be transcribed.' => 'Ses metne çevrilemedi.',
  'The audio file could not be read.' => 'Ses dosyası okunamadı.',
  'Voice message (%1$s) transcribed: %2$s' => 'Sesli mesaj (%1$s) metne çevrildi: %2$s',
  'Voice message (%1$s) could not be processed: %2$s' => 'Sesli mesaj (%1$s) dinlenemedi: %2$s',
  'This action is not available on an official WhatsApp Cloud API line.' => 'Resmi WhatsApp Cloud API hattında bu işlem yok.',
  'WhatsApp 24-hour rule: the contact has not written in the last 24 hours, so the Cloud API will not send a free-form message; only an approved template can be sent. Try again once they write.' => 'WhatsApp 24 saat kuralı: kişi son 24 saatte yazmadığı için Cloud API serbest mesaj göndermiyor; yalnız onaylı şablon gider. Kişi yazınca yeniden deneyin.',
  'A Cloud API line needs Flux Mail 1.10.0 or later.' => 'Cloud API hattı için Flux Mail 1.10.0 veya üstü gerekli.',
  'The Cloud API cannot send to this address (hidden number or group).' => 'Cloud API bu adrese (gizli numara ya da grup) gönderemez.',
  'Could not reach the Cloud API account (İletişim › Connections).' => 'Cloud API hesabına ulaşılamadı (İletişim › Bağlantılar).',
  'A Cloud API line has no QR code; the account is set up in İletişim › Connections.' => 'Cloud API hattında QR yok; hesap İletişim › Bağlantılar\'da kurulur.',
  'The file could not be prepared.' => 'Dosya hazırlanamadı.',
  'Flux AI has no image support.' => 'Flux AI görsel desteği yok.',
  'The image could not be rendered.' => 'Görsel çevrilemedi.',
  'The assistant\'s image could not be sent: ' => 'Asistanın görseli gönderilemedi: ',
  'Hello {first_name}, we have created your donation record: {donation}, total {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'After paying, you can send the receipt here. Thank you.' => 'Merhaba {first_name}, bağış kaydınızı oluşturduk: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'Ödemeyi yaptıktan sonra dekontu buradan gönderebilirsiniz. Teşekkür ederiz.',
  'Hello {first_name}, your donation has been recorded: {donation}, total {amount}.' . chr(10) . '' . chr(10) . 'Thank you for your support.' => 'Merhaba {first_name}, bağışınız kaydedildi: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . 'Desteğiniz için teşekkür ederiz.',
  'The plugin that would run this scenario is inactive.' => 'Bu senaryoyu oynatacak eklenti kapalı.',
  'This user is not allowed to use the staff tools.' => 'Bu kullanıcının personel araçları yetkisi yok.',
  '%1$s linked this chat to staff member %2$s' => '%1$s bu sohbeti personel olarak bağladı: %2$s',
