  'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.' => 'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.',
  'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.' => 'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.',
  'Hide' => 'Gizle',
  'Show' => 'Göster',
  'Deleted for everyone' => 'Herkesten silindi',
  'Hidden in the panel' => 'Panelde gizlendi',
  'Delete for everyone' => 'Herkesten sil',
  'Hide in the panel only' => 'Yalnız panelde gizle',
  'WhatsApp doesn\'t allow deleting a received message for everyone; it stays on the contact\'s phone and is only hidden in the panel.' => 'Gelen mesajı WhatsApp karşı taraftan silmeye izin vermez; mesaj kişinin telefonunda kalır, yalnız panelde gizlenir.',
  'Delete for everyone is turned off in the settings; the message is only hidden in the panel and stays on the contact\'s phone.' => 'Herkesten silme ayarlarda kapalı; mesaj yalnız panelde gizlenir, kişinin telefonunda kalır.',
  'This channel doesn\'t support delete for everyone; the message is only hidden in the panel and stays on the contact\'s phone.' => 'Bu kanalda herkesten silme desteklenmiyor; mesaj yalnız panelde gizlenir, kişinin telefonunda kalır.',
  'The time limit for delete for everyone has passed (WhatsApp allows about {h} hours after sending). The message stays on the contact\'s phone and is only hidden in the panel.' => 'Herkesten silme süresi doldu (WhatsApp gönderimden sonra yaklaşık {h} saat izin verir). Mesaj kişinin telefonunda kalır, yalnız panelde gizlenir.',
  'Only the sender or an administrator can delete this message for everyone; you can hide it in the panel.' => 'Bu mesajı yalnız gönderen ya da yönetici herkesten silebilir; siz panelde gizleyebilirsiniz.',
  'If deleted for everyone, the message also turns into "This message was deleted" on the contact\'s phone. Time left: about {n} hours.' => 'Herkesten silinirse mesaj kişinin telefonunda da "Bu mesaj silindi" olur. Kalan süre: yaklaşık {n} saat.',
  'Deleted messages are kept on the server: the chat shows a "This message was deleted" line and the team can click it to see the content. AI does not read deleted messages.' => 'Silinen mesaj sunucuda saklanır: sohbette "Bu mesaj silindi" satırı görünür, ekip tıklayıp içeriği açabilir. Yapay zekâ silinen mesajı okumaz.',
  'Message not found.' => 'Mesaj bulunamadı.',
  'This message was already deleted.' => 'Bu mesaj zaten silinmiş.',
  'Only the sender or an administrator can delete this message for everyone.' => 'Bu mesajı yalnız gönderen ya da yönetici herkesten silebilir.',
  'This message can\'t be deleted for everyone on this channel. You can hide it in the panel instead.' => 'Bu mesaj bu kanalda herkesten silinemez. Bunun yerine panelde gizleyebilirsiniz.',
  'The time limit for deleting for everyone has passed. You can hide it in the panel instead.' => 'Herkesten silme süresi doldu. Bunun yerine panelde gizleyebilirsiniz.',
  'WhatsApp did not delete the message.' => 'WhatsApp mesajı silmedi.',
  'Delete for everyone time limit (hours)' => 'Herkesten silme süresi (saat)',
  'WhatsApp lets you delete a sent message for everyone only for about 2 days and 12 hours (60 hours). After this limit, or for received messages, the message is only hidden in the panel: it stays on the contact\'s phone. 0 turns off delete for everyone. Deleted messages are never removed from the server; the team can still open them.' => 'WhatsApp gönderilen mesajı herkesten silmeye yalnız yaklaşık 2 gün 12 saat (60 saat) izin verir. Bu süre geçince ya da gelen mesajlarda mesaj yalnız panelde gizlenir, kişinin telefonunda kalır. 0 herkesten silmeyi kapatır. Silinen mesajlar sunucudan hiç kaldırılmaz; ekip yine açıp görebilir.',
  'Last update request %1$s. While the panel is open it checks for new messages every %2$d s (3 s while a reply is streaming, up to 15 s when nothing changes) and once a minute in a background tab.' => 'Son güncelleme isteği %1$s. Panel açıkken %2$d sn\'de bir yeni mesaj sorulur (cevap akarken 3 sn, değişiklik yoksa 15 sn\'ye kadar) ve arka plandaki sekmede dakikada bir.',
  'The open tab checks for new messages at this interval (10 recommended), every 3 s while a reply is streaming, and up to 15 s when nothing changes. A background tab checks once a minute. Errors back off up to 60 s.' => 'Açık sekmede bu aralıkla yeni mesaj kontrol edilir (önerilen 10); cevap akarken 3 sn\'de bir, değişiklik yoksa 15 sn\'ye kadar. Arka plandaki sekme dakikada bir bakar. Hatalarda aralık 60 sn\'ye kadar seyrekleşir.',
  'Flux Donate is not active.' => 'Flux Donate etkin değil.',
